import re, json, collections
BASE='/private/tmp/live-spec-night18/wt-int/'
spec=open(BASE+'PRODUCT_SPEC.md').read()
# split requirements
parts=re.split(r'^## Requirement (\d+):(.*)$', spec, flags=re.M)
reqs={}
order=[]
for i in range(1,len(parts),3):
    n=int(parts[i]); title=parts[i+1].strip(); body=parts[i+2]
    reqs[n]=(title,body); order.append(n)
print("count",len(order))
# anchors per requirement
anch={}
for n,(t,b) in reqs.items():
    codes=set(re.findall(r'\b((?:INV|E|T|A|M|S|C|D|B|ACT|G|P|R)-\d+)\b', b))
    anch[n]=codes
# matrix reference
tm=open(BASE+'TEST_MATRIX.md').read()
ref=tm.split('\n## Reference')[-1]
a2rows={}
for line in ref.splitlines():
    m=re.match(r'\|\s*([A-Z]+-\d+)\s*\|\s*(.+?)\s*\|$', line)
    if m:
        a2rows[m.group(1)]=re.findall(r'M-\d+', m.group(2))
# matrix node per row
tmrows={}
node=None
for line in tm.splitlines():
    m=re.match(r'### \[node: (.+?)\]?\]?$', line)
    if line.startswith('### [node:'):
        node=line[len('### [node: '):].rstrip(']').replace(' [target','').strip()
    m=re.match(r'\|\s*(M-\d+)\s*\|', line)
    if m: tmrows[m.group(1)]=node
# architecture owns
arch=open(BASE+'ARCHITECTURE.md').read()
a2node=collections.defaultdict(set)
cur=None; inowns=False
for line in arch.splitlines():
    if line.startswith('### [node:'):
        cur=line[len('### [node: '):].rstrip(']').replace('] [target','').replace(' [target','').strip().rstrip(']')
        inowns=False
    elif line.startswith('**owns**'): inowns=True
    elif line.startswith('**') and not line.startswith('**owns**'): inowns=False
    elif inowns and cur and line.startswith('- '):
        head=line.split('(')[0]
        for c in re.findall(r'\b((?:INV|E|T|A|M|S|C|D|B|ACT)-\d+)\b', head):
            a2node[c].add(cur)
out={}
for n in order:
    rows=set(); nodes=set()
    for c in anch[n]:
        for r in a2rows.get(c,[]): rows.add(r)
        for nd in a2node.get(c,[]): nodes.add(nd)
    out[n]={'title':reqs[n][0],'anchors':sorted(anch[n]),'rows':sorted(rows),'nodes':sorted(nodes)}
json.dump(out,open('/private/tmp/claude-501/-private-tmp-live-spec-green-candidate/61f5a05d-28d5-4951-9a1f-a62262e79613/scratchpad/map.json','w'),indent=0)
for n in order[:5]:
    print(n,out[n]['title'],out[n]['nodes'],out[n]['rows'][:6])
EOF
